create table attachment(id bigint generated by default as identity primary key,version bigint not null default 0,owner_type varchar(255) not null,owner_id bigint not null,filename varchar(255),media_type varchar(255),bytes integer not null,uploaded_by varchar(255),created_at timestamptz,content text);
create index ix_attachment_owner on attachment(owner_type,owner_id);
create table report_subject(id bigint generated by default as identity primary key,version bigint not null default 0,report_id bigint not null references report(id),patron_id bigint not null references patron(id),relationship varchar(255),unique(report_id,patron_id));
